package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;

import java.lang.reflect.Method;
import java.util.Arrays;

import org.eclipse.rdf4j.model.base.CoreDatatype;
import org.eclipse.rdf4j.sail.lmdb.ValueIds;
import org.eclipse.rdf4j.sail.lmdb.evaluation.NativeLmdbQuerySource.NativeAdjacency;
import org.junit.jupiter.api.Test;

class LmdbNativeAdjacencyBatchContractTest {

	@Test
	void exposesPhysicalGrainsAndPrimitiveAdjacencyBatches() throws Exception {
		Class<?> grain = Class.forName(LmdbNativeKernelIr.class.getName() + "$Grain");
		assertThat(Arrays.stream(grain.getEnumConstants()).map(Object::toString))
				.containsExactly("PLANE", "ROOT", "FIBER", "QUAD");

		Class<?> planeBatch = nestedClass("PlaneBatch");
		Class<?> rootBatch = nestedClass("RootBatch");
		Class<?> fiberBatch = nestedClass("FiberBatch");
		assertThat(planeBatch.getDeclaredConstructor(int.class)).isNotNull();
		assertThat(rootBatch.getDeclaredConstructor(int.class)).isNotNull();
		assertThat(fiberBatch.getDeclaredConstructor(int.class)).isNotNull();
		assertThat(rootBatch.getMethod("uniformRootIdType").getReturnType()).isEqualTo(int.class);
		assertThat(fiberBatch.getMethod("uniformNeighborIdType").getReturnType()).isEqualTo(int.class);
		assertThat(rootBatch.getMethod("uniformRootTermKind").getReturnType()).isEqualTo(int.class);
		assertThat(rootBatch.getMethod("uniformRootCoreDatatypeTag").getReturnType()).isEqualTo(int.class);
		assertThat(fiberBatch.getMethod("uniformNeighborTermKind").getReturnType()).isEqualTo(int.class);
		assertThat(fiberBatch.getMethod("uniformNeighborCoreDatatypeTag").getReturnType()).isEqualTo(int.class);

		Method fillRoots = NativeAdjacency.KeyRunCursor.class.getMethod("fillRoots", int.class, rootBatch);
		Method fillFibers = NativeAdjacency.KeyRunCursor.class.getMethod("fillFibers", fiberBatch);
		assertThat(fillRoots.getReturnType()).isEqualTo(int.class);
		assertThat(fillFibers.getReturnType()).isEqualTo(int.class);
	}

	@Test
	void scalarBatchesPreserveRootAndFiberMultiplicity() {
		NativeAdjacency adjacency = new BatchFixtureAdjacency();
		NativeAdjacency.RootBatch roots = new NativeAdjacency.RootBatch(1);
		try (NativeAdjacency.KeyRunCursor cursor = adjacency.openKeyRunCursor()) {
			assertThat(cursor.fillRoots(7, roots)).isEqualTo(1);
			assertThat(roots.rootIds()).startsWith(11L);
			assertThat(roots.predicateOrdinals()).startsWith(7);
			assertThat(roots.runHandles()).startsWith(1L);
			assertThat(roots.quadMultiplicities()).startsWith(3L);
			assertThat(roots.flags()).startsWith(0);

			assertThat(cursor.fillRoots(7, roots)).isEqualTo(1);
			assertThat(roots.rootIds()).startsWith(22L);
			assertThat(roots.runHandles()).startsWith(2L);
			assertThat(roots.quadMultiplicities()).startsWith(1L);
			assertThat(cursor.fillRoots(7, roots)).isZero();
		}

		try (NativeAdjacency.KeyRunCursor cursor = adjacency.openKeyRunCursor()) {
			assertThat(cursor.advance()).isTrue();
			NativeAdjacency.FiberBatch fibers = new NativeAdjacency.FiberBatch(1);
			assertThat(cursor.fillFibers(fibers)).isEqualTo(1);
			assertThat(fibers.neighborIds()).startsWith(100L);
			assertThat(fibers.contextMultiplicities()).startsWith(2L);
			assertThat(cursor.fillFibers(fibers)).isEqualTo(1);
			assertThat(fibers.neighborIds()).startsWith(101L);
			assertThat(fibers.contextMultiplicities()).startsWith(1L);
			assertThat(cursor.fillFibers(fibers)).isZero();
		}
	}

	@Test
	void batchesReportUniformAndMixedIdTypes() {
		NativeAdjacency adjacency = new BatchFixtureAdjacency();
		NativeAdjacency.RootBatch roots = new NativeAdjacency.RootBatch(2);
		assertThat(roots.uniformRootIdType()).isEqualTo(NativeAdjacency.RootBatch.EMPTY_ID_TYPE);
		try (NativeAdjacency.KeyRunCursor cursor = adjacency.openKeyRunCursor()) {
			assertThat(cursor.fillRoots(7, roots)).isEqualTo(2);
			assertThat(roots.uniformRootIdType()).isEqualTo(NativeAdjacency.RootBatch.MIXED_ID_TYPES);
			assertThat(roots.uniformRootTermKind()).isEqualTo(NativeAdjacency.RootBatch.MIXED_TERM_KINDS);
			assertThat(roots.uniformRootCoreDatatypeTag())
					.isEqualTo(ValueIds.coreDatatypeTag(CoreDatatype.XSD.DOUBLE));
		}
		roots.clear();
		assertThat(roots.uniformRootIdType()).isEqualTo(NativeAdjacency.RootBatch.EMPTY_ID_TYPE);
		assertThat(roots.uniformRootTermKind()).isEqualTo(NativeAdjacency.RootBatch.EMPTY_TERM_KIND);
		assertThat(roots.uniformRootCoreDatatypeTag())
				.isEqualTo(NativeAdjacency.RootBatch.EMPTY_CORE_DATATYPE_TAG);

		try (NativeAdjacency.KeyRunCursor cursor = adjacency.openKeyRunCursor()) {
			assertThat(cursor.advance()).isTrue();
			NativeAdjacency.FiberBatch fibers = new NativeAdjacency.FiberBatch(4);
			assertThat(cursor.fillFibers(fibers)).isEqualTo(2);
			assertThat(fibers.uniformNeighborIdType()).isEqualTo(NativeAdjacency.FiberBatch.MIXED_ID_TYPES);
			assertThat(fibers.uniformNeighborTermKind()).isEqualTo(ValueIds.TERM_KIND_LITERAL);
			assertThat(fibers.uniformNeighborCoreDatatypeTag()).isZero();
		}
	}

	@Test
	void rootBatchRetainsTermKindAcrossIdCodesAndReportsUniformCoreDatatype() {
		NativeAdjacency.RootBatch roots = new NativeAdjacency.RootBatch(4);
		long integerReference = ValueIds.createCoreLiteralReferenceId(1L, CoreDatatype.XSD.INTEGER);
		long anotherIntegerReference = ValueIds.createCoreLiteralReferenceId(2L, CoreDatatype.XSD.INTEGER);
		long inlineInteger = ValueIds.createId(ValueIds.T_INTEGER, 3L);
		roots.append(integerReference, 0, 0L, 1L, 1L, 0);
		roots.append(anotherIntegerReference, 0, 0L, 1L, 1L, 0);
		roots.append(inlineInteger, 0, 0L, 1L, 1L, 0);

		assertThat(roots.uniformRootIdType()).isEqualTo(NativeAdjacency.RootBatch.MIXED_ID_TYPES);
		assertThat(roots.uniformRootTermKind()).isEqualTo(ValueIds.TERM_KIND_LITERAL);
		assertThat(roots.uniformRootCoreDatatypeTag())
				.isEqualTo(ValueIds.coreDatatypeTag(CoreDatatype.XSD.INTEGER));

		roots.append(ValueIds.createCoreLiteralReferenceId(3L, CoreDatatype.XSD.STRING), 0, 0L, 1L, 1L, 0);
		assertThat(roots.uniformRootTermKind()).isEqualTo(ValueIds.TERM_KIND_LITERAL);
		assertThat(roots.uniformRootCoreDatatypeTag()).isZero();
	}

	@Test
	void retainedRunFiberBatchesUseBulkNeighborsAcrossBoundaries() {
		BulkFiberAdjacency adjacency = new BulkFiberAdjacency();
		NativeAdjacency.FiberBatch fibers = new NativeAdjacency.FiberBatch(2);

		assertThat(adjacency.fillFibers(77L, 1L, fibers)).isEqualTo(2);
		assertThat(fibers.neighborIds()).startsWith(5L, 6L);
		assertThat(fibers.contextMultiplicities()).startsWith(1_500L, 700L);
		assertThat(adjacency.fillFibers(77L, 1L, fibers)).isEqualTo(1);
		assertThat(fibers.neighborIds()).startsWith(7L);
		assertThat(fibers.contextMultiplicities()).startsWith(300L);
		assertThat(adjacency.fillFibers(77L, 1L, fibers)).isZero();
		assertThat(adjacency.bulkCopies).isGreaterThan(1);
		assertThat(adjacency.contextReads).isZero();
	}

	private static Class<?> nestedClass(String name) {
		return Arrays.stream(NativeAdjacency.class.getDeclaredClasses())
				.filter(candidate -> candidate.getSimpleName().equals(name))
				.findFirst()
				.orElseThrow(() -> new AssertionError("Missing primitive adjacency batch " + name));
	}

	private static final class BatchFixtureAdjacency implements NativeAdjacency {
		private final long[][] rows = { { 100L, 100L, 101L }, { 200L } };

		@Override
		public long find(long key) {
			return key == 11L ? 1L : key == 22L ? 2L : NOT_FOUND;
		}

		@Override
		public long size(long runHandle) {
			return rows[Math.toIntExact(runHandle - 1L)].length;
		}

		@Override
		public long neighborAt(long runHandle, long runOffset) {
			return rows[Math.toIntExact(runHandle - 1L)][Math.toIntExact(runOffset)];
		}

		@Override
		public long contextAt(long runHandle, long runOffset) {
			return runOffset;
		}

		@Override
		public boolean supportsKeyEnumeration() {
			return true;
		}

		@Override
		public boolean keysImplyNonEmptyRuns() {
			return true;
		}

		@Override
		public long keyCount() {
			return 2L;
		}

		@Override
		public long keyAt(long keyOrdinal) {
			return keyOrdinal == 0L ? 11L : 22L;
		}
	}

	private static final class BulkFiberAdjacency implements NativeAdjacency {
		private final long[] neighbors = new long[2_500];
		private int bulkCopies;
		private int contextReads;

		private BulkFiberAdjacency() {
			Arrays.fill(neighbors, 0, 1_500, 5L);
			Arrays.fill(neighbors, 1_500, 2_200, 6L);
			Arrays.fill(neighbors, 2_200, 2_500, 7L);
		}

		@Override
		public long find(long key) {
			return key == 77L ? 1L : NOT_FOUND;
		}

		@Override
		public long size(long runHandle) {
			return neighbors.length;
		}

		@Override
		public long neighborAt(long runHandle, long runOffset) {
			throw new AssertionError("bulk fiber enumeration must not use scalar neighborAt");
		}

		@Override
		public int copyNeighbors(long runHandle, long runOffset, int length, long[] target, int targetOffset) {
			int copied = Math.min(length, neighbors.length - Math.toIntExact(runOffset));
			System.arraycopy(neighbors, Math.toIntExact(runOffset), target, targetOffset, copied);
			bulkCopies++;
			return copied;
		}

		@Override
		public long contextAt(long runHandle, long runOffset) {
			contextReads++;
			throw new AssertionError("unrestricted fiber enumeration must not read contexts");
		}

		@Override
		public boolean runsNeighborOrdered() {
			return true;
		}
	}
}
